#!/usr/bin/env bash
set -euo pipefail

# Offline project-skill discovery. Preserve real platform directories and
# unrelated links; retire only links generated by this repository's old sync.
ROOT="$(cd "$(dirname "$0")" && pwd)"
AGENT_SKILLS="$ROOT/.agents/skills"
DESTS=("$ROOT/.agents/skills" "$ROOT/.claude/skills" "$ROOT/.cursor/skills")

for DEST in "${DESTS[@]}"; do
  mkdir -p "$DEST"
  for ENTRY in "$DEST"/*; do
    [ -L "$ENTRY" ] || continue
    TARGET="$(readlink "$ENTRY")"
    case "$TARGET" in
      ../../.skills-upstream/*) unlink "$ENTRY" ;;
      ../../.agents/skills/*)
        [ -f "$ENTRY/SKILL.md" ] || unlink "$ENTRY"
        ;;
    esac
  done
done

project_count=0
for SOURCE in "$AGENT_SKILLS"/*; do
  [ -d "$SOURCE" ] && [ ! -L "$SOURCE" ] || continue
  [ -f "$SOURCE/SKILL.md" ] || continue
  NAME="$(basename "$SOURCE")"
  for DEST in "$ROOT/.claude/skills" "$ROOT/.cursor/skills"; do
    ENTRY="$DEST/$NAME"
    if [ -L "$ENTRY" ]; then
      TARGET="$(readlink "$ENTRY")"
      if [ "$TARGET" != "../../.agents/skills/$NAME" ]; then
        echo "Preserved custom link: ${ENTRY#$ROOT/}"
      fi
      continue
    fi
    [ ! -e "$ENTRY" ] || continue
    ln -s "../../.agents/skills/$NAME" "$ENTRY"
  done
  project_count=$((project_count + 1))
done

echo "Project skills available: $project_count"
echo "Vendor discovery disabled; no network or vendor checkout changes."
